# build_default_menus recreates what the hand-written navbar/sidemenu/shortcut
# templates and the show_in_menu flags showed before this migration, as
# editable MenuGroups and Menus (see models/menus.py). A frozen copy on
# purpose -- seed_dev_data builds its own for fresh databases. Does nothing on
# a database with no article pages yet. Forward-only: reversing can't restore the
# removed show_in_menu values.

EXTERNAL = {
    "peoply": "https://peoply.app/",
    "navet_events": "https://ifinavet.no/events",
    "dagen_program": "https://dagenatifi.no/program/",
    "dagen_jobs": "https://dagenatifi.no/stillingsannonser/",
    "navet_jobs": "https://ifinavet.no/job-listings",
}


def build_default_menus(apps, schema_editor):
    Locale = apps.get_model("wagtailcore", "Locale")
    Page = apps.get_model("wagtailcore", "Page")
    ArticleIndexPage = apps.get_model("ifi_home_app", "ArticleIndexPage")
    EventIndexPage = apps.get_model("ifi_home_app", "EventIndexPage")
    CategoryPage = apps.get_model("ifi_home_app", "CategoryPage")
    StudentUnionCategoryPage = apps.get_model(
        "ifi_home_app", "StudentUnionCategoryPage"
    )
    UnionPage = apps.get_model("ifi_home_app", "UnionPage")
    Menu = apps.get_model("ifi_home_app", "Menu")
    MenuGroup = apps.get_model("ifi_home_app", "MenuGroup")
    MenuGroupLink = apps.get_model("ifi_home_app", "MenuGroupLink")
    MenuSlot = apps.get_model("ifi_home_app", "MenuSlot")

    nb = Locale.objects.filter(language_code="nb").first()
    en = Locale.objects.filter(language_code="en").first()
    if (
        nb is None
        or Menu.objects.exists()
        or not ArticleIndexPage.objects.filter(locale=nb).exists()
    ):
        return

    def nb_page(model, **filters):
        return (
            model.objects.filter(locale=nb, live=True, **filters)
            .order_by("path")
            .first()
        )

    def children(parent, model=Page, **filters):
        if parent is None:
            return []
        return list(
            model.objects.filter(
                locale=nb,
                live=True,
                path__startswith=parent.path,
                depth=parent.depth + 1,
                **filters,
            ).order_by("path")
        )

    def flagged_categories_under(index):
        if index is None:
            return []
        return list(
            CategoryPage.objects.filter(
                locale=nb, live=True, show_in_menu=True, path__startswith=index.path
            ).order_by("path")
        )

    def pages(page_list):
        return [{"page": page} for page in page_list if page is not None]

    def group(title_nb, title_en, link_page=None, links=(), short_nb="", short_en=""):
        key = uuid.uuid4()
        link_keys = [uuid.uuid4() for _ in links]
        copies = [(nb, "nb", title_nb, short_nb)]
        if en is not None:
            copies.append((en, "en", title_en, short_en))
        nb_group = None
        for locale, lang, title, short in copies:
            menu_group = MenuGroup.objects.create(
                translation_key=key,
                locale=locale,
                title=title,
                short_title=short,
                link_page_id=link_page.pk if link_page else None,
            )
            for order, (link, link_key) in enumerate(zip(links, link_keys)):
                page = link.get("page")
                MenuGroupLink.objects.create(
                    group=menu_group,
                    translation_key=link_key,
                    locale=locale,
                    sort_order=order,
                    page_id=page.pk if page else None,
                    url=link.get("url", ""),
                    label=link.get(f"label_{lang}", ""),
                    prefix=link.get(f"prefix_{lang}", ""),
                    description=link.get("description", ""),
                )
            if lang == "nb":
                nb_group = menu_group
        return nb_group

    def menu(key, slots):
        menu_obj = Menu.objects.create(key=key)
        for order, (menu_group, column, hide_on_mobile) in enumerate(slots):
            MenuSlot.objects.create(
                menu=menu_obj,
                group=menu_group,
                sort_order=order,
                column=column,
                hide_on_mobile=hide_on_mobile,
            )

    info_index = nb_page(ArticleIndexPage, section="info_articles")
    news_index = nb_page(ArticleIndexPage, section="news")
    event_index = nb_page(EventIndexPage)
    help_category = nb_page(CategoryPage, slug="hjelp")
    unions_category = nb_page(StudentUnionCategoryPage, slug="studentforeninger")
    tools_category = nb_page(CategoryPage, slug="ifi-verktøy")
    new_student_category = nb_page(CategoryPage, slug="ny-ifi-student")

    info = group(
        "Infoartikkler",
        "Info Articles",
        info_index,
        pages(flagged_categories_under(info_index)),
    )
    news = group(
        "Nyheter", "News", news_index, pages(flagged_categories_under(news_index))
    )
    events = group("Arrangementer", "Events", event_index)
    help_group = group(
        "hJELP",
        "hELP",
        help_category,
        pages(children(help_category, CategoryPage, show_in_menu=True)),
    )
    unions = group(
        "Studentforeninger",
        "Student Unions",
        unions_category,
        pages(children(unions_category, UnionPage, show_in_menu=True)),
        short_nb="Foreninger",
        short_en="Unions",
    )
    tools = group("Verktøy", "Tools", tools_category, pages(children(tools_category)))
    new_student = group(
        "Ny Student?",
        "New Student?",
        new_student_category,
        pages(children(new_student_category)),
    )

    shortcut_info = group(
        "Info",
        "Info",
        info_index,
        pages(
            nb_page(CategoryPage, slug=slug)
            for slug in ("akademisk", "praktisk", "sosialt", "hjelp")
        ),
    )
    shortcut_unions = group("Foreninger", "Unions", unions_category)
    shortcut_events = group(
        "Arrangementer",
        "Events",
        event_index,
        [
            *(
                [{"page": event_index, "label_nb": "Alle", "label_en": "All"}]
                if event_index
                else []
            ),
            {
                "url": EXTERNAL["peoply"],
                "label_nb": "Foreningsarrangementer",
                "label_en": "Union Events",
                "description": "Peoply",
            },
            {
                "url": EXTERNAL["navet_events"],
                "label_nb": "Bedriftspresentasjoner",
                "label_en": "Company Presentations",
                "description": "Navet",
            },
            {
                "url": EXTERNAL["dagen_program"],
                "label_nb": "Karrieredag",
                "label_en": "Career Day",
                "description": "dagen@ifi",
            },
        ],
    )
    jobs = group(
        "Stillingsannonser",
        "Job Listings",
        None,
        [
            {
                "url": EXTERNAL["dagen_jobs"],
                "label_nb": "dagen@ifi",
                "label_en": "dagen@ifi",
                "prefix_nb": "Annonser hos",
                "prefix_en": "Listings at",
            },
            {
                "url": EXTERNAL["navet_jobs"],
                "label_nb": "Navet",
                "label_en": "Navet",
                "prefix_nb": "Annonser hos",
                "prefix_en": "Listings at",
            },
        ],
    )

    menu(
        "sidemenu",
        [
            (info, 1, False),
            (news, 1, False),
            (events, 1, False),
            (help_group, 1, False),
        ],
    )
    menu(
        "home_dropmenu",
        [
            (news, 1, True),
            (info, 1, True),
            (unions, 1, False),
            (tools, 1, False),
            (new_student, 1, False),
        ],
    )
    menu(
        "shortcuts",
        [
            (shortcut_info, 1, False),
            (shortcut_unions, 1, False),
            (news, 2, False),
            (shortcut_events, 2, False),
            (jobs, 3, False),
            (tools, 3, False),
        ],
    )


